 public List<Map<String,Object>> templateReferences(String type){return templateReferences(type,null);}
 public List<Map<String,Object>> templateReferences(String type,Long requested){
  Long factory=scope.resolveFactory(requested);
  if(Set.of("RAW_IN","PROCESS_RAW_RETURN","RAW_PROCESS_IN").contains(type))return jdbc.queryForList("SELECT CAST(m.material_id AS CHAR) id,m.material_code code,CONCAT(t.name,m.material_type) name,m.material_type,m.metal_type_id,t.name metal_type_name,m.specification FROM metal_material m JOIN metal_type t ON t.metal_type_id=m.metal_type_id WHERE m.del_flag='0' AND m.factory_id=? AND t.factory_id=m.factory_id ORDER BY m.material_id",factory);
  if(Set.of("SEMI_IN","FINISHED_IN","RAW_PROCESS_IN").contains(type))return jdbc.queryForList("SELECT CAST(product_id AS CHAR) id,product_code code,product_name name,specification FROM metal_product WHERE del_flag='0' AND factory_id=? ORDER BY product_id",factory);
  throw new ServiceException("参考资料仅支持入库类型");
 }
